# Let me also check the "bash: read" then "bash: cat" double-read pattern more precisely
python3 << 'EOF'
import json, os, glob

double_reads = {}  # agent -> count
wasted_cost = {}  # agent -> estimated wasted $

for meta_path in glob.glob('.state/sessions/history/*/meta.json'):
    sid = os.path.basename(os.path.dirname(meta_path))
    ts_str = sid.split('_')[1]
    try:
        ts = int(ts_str)
    except:
        continue
    if ts < 1774143540000:
        continue

    with open(meta_path) as f:
        meta = json.load(f)
    agent = meta.get('agent', '?')

    jsonl_path = os.path.join(os.path.dirname(meta_path), 'session.jsonl')
    if not os.path.exists(jsonl_path):
        continue

    msgs = []
    with open(jsonl_path) as f:
        for line in f:
            try:
                d = json.loads(line)
                msgs.append(d)
            except:
                continue

    # Look for pattern: bash("read file") -> result -> bash("cat file")
    for i in range(len(msgs) - 2):
        if msgs[i].get('role') != 'assistant':
            continue
        content = msgs[i].get('content', [])
        if not isinstance(content, list):
            continue
        for block in content:
            if isinstance(block, dict) and block.get('type') == 'toolCall' and block.get('name') == 'bash':
                cmd = block.get('arguments', {}).get('command', '')
                if cmd.startswith('read ') or cmd.startswith('read\n'):
                    # Check if next assistant msg uses cat on same file(s)
                    for j in range(i+1, min(i+4, len(msgs))):
                        if msgs[j].get('role') == 'assistant':
                            jcontent = msgs[j].get('content', [])
                            if isinstance(jcontent, list):
                                for jblock in jcontent:
                                    if isinstance(jblock, dict) and jblock.get('type') == 'toolCall' and jblock.get('name') == 'bash':
                                        jcmd = jblock.get('arguments', {}).get('command', '')
                                        if jcmd.startswith('cat '):
                                            double_reads[agent] = double_reads.get(agent, 0) + 1
                                            # Cost of the wasted "read" call
                                            cost = msgs[i].get('usage', {}).get('cost', {})
                                            c = cost.get('total', 0) if isinstance(cost, dict) else 0
                                            wasted_cost[agent] = wasted_cost.get(agent, 0) + c
                            break

print("=== BASH 'read' THEN 'cat' DOUBLE-READ PATTERN ===")
for agent, count in sorted(double_reads.items(), key=lambda x: -x[1]):
    cost = wasted_cost.get(agent, 0)
    print(f"  {agent:<12} {count:>3} double-reads, ~${cost:.4f} wasted")

print(f"\nTotal double-reads: {sum(double_reads.values())}, ~${sum(wasted_cost.values()):.4f} wasted")
EOF

