import json, os, glob

for meta_path in glob.glob('.state/sessions/history/*/meta.json'):
    sid = os.path.basename(os.path.dirname(meta_path))
    ts_str = sid.split('_')[1]
    try:
        ts = int(ts_str)
    except:
        continue
    if ts < 1774143540000:
        continue

    with open(meta_path) as f:
        meta = json.load(f)
    if meta.get('agent') != 'optimizer':
        continue

    jsonl_path = os.path.join(os.path.dirname(meta_path), 'session.jsonl')
    if not os.path.exists(jsonl_path):
        continue

    with open(jsonl_path) as f:
        lines = f.readlines()

    large_count = 0
    for i, line in enumerate(lines):
        d = json.loads(line)
        if d.get('role') == 'toolResult' and len(line) > 50000:
            large_count += 1

    if large_count > 0:
        cost = 0
        for line in lines:
            d = json.loads(line)
            if d.get('role') == 'assistant':
                c = d.get('usage', {}).get('cost', {})
                cost += c.get('total', 0) if isinstance(c, dict) else 0
        print(f"\n{sid} — ${cost:.2f}, {large_count} large reads")
        # Show the large results
        for i, line in enumerate(lines):
            d = json.loads(line)
            if d.get('role') == 'toolResult' and len(line) > 50000:
                # What did it read?
                content = d.get('content', [])
                preview = ''
                if isinstance(content, list):
                    for block in content:
                        if isinstance(block, dict):
                            preview = block.get('text', '')[:150].replace('\n', ' ')
                            break
                elif isinstance(content, str):
                    preview = content[:150].replace('\n', ' ')
                # Check what tool call came before
                for j in range(i-1, -1, -1):
                    pline = lines[j]
                    pd = json.loads(pline)
                    if pd.get('role') == 'assistant':
                        pcontent = pd.get('content', [])
                        if isinstance(pcontent, list):
                            for block in pcontent:
                                if isinstance(block, dict) and block.get('type') == 'toolCall':
                                    tool = block.get('name', '?')
                                    args = block.get('arguments', {})
                                    if tool == 'bash':
                                        cmd = args.get('command', '')[:100]
                                    elif tool == 'read':
                                        cmd = f"read({args.get('path', '?')})"
                                    else:
                                        cmd = f"{tool}()"
                                    print(f"  msg {i}: {len(line)//1024}KB — {cmd}")
                        break
